class MinHeap {
  #arr = [];
  push(v) {
    this.#arr.push(v);
    let i = this.#arr.length - 1;
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (this.#arr[p] <= this.#arr[i]) break;
      [this.#arr[p], this.#arr[i]] = [this.#arr[i], this.#arr[p]];
      i = p;
    }
  }
  pop() {
    const top = this.#arr[0];
    const last = this.#arr.pop();
    if (this.#arr.length) {
      this.#arr[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = 2 * i + 2;
        let s = i;
        if (l < this.#arr.length && this.#arr[l] < this.#arr[s]) s = l;
        if (r < this.#arr.length && this.#arr[r] < this.#arr[s]) s = r;
        if (s === i) break;
        [this.#arr[s], this.#arr[i]] = [this.#arr[i], this.#arr[s]];
        i = s;
      }
    }
    return top;
  }
}

const h = new MinHeap();
[5, 2, 8, 1, 9].forEach((v) => h.push(v));
[h.pop(), h.pop(), h.pop()];

function heapSort(arr) {
  const h = new MinHeap();
  for (const v of arr) h.push(v);
  const out = [];
  for (let i = 0; i < arr.length; i++) out.push(h.pop());
  return out;
}
